CREATE TABLE Livro (codl INT AUTO_INCREMENT NOT NULL, Titulo VARCHAR(40) NOT NULL, Editora VARCHAR(40) NOT NULL, Edicao INT NOT NULL, AnoPublicacao VARCHAR(4) NOT NULL, Valor NUMERIC(10, 2) NOT NULL, PRIMARY KEY (codl)) DEFAULT CHARACTER SET utf8mb4;
