CREATE TABLE Livro_Assunto (Livro_Codl INT NOT NULL, Assunto_codAs INT NOT NULL, INDEX IDX_2F01B7434A5AFC39 (Livro_Codl), INDEX IDX_2F01B743A5E1B302 (Assunto_codAs), PRIMARY KEY (Livro_Codl, Assunto_codAs)) DEFAULT CHARACTER SET utf8mb4;
